// Recipes: the exact render_coupled arguments behind the approved renders,
// with 1-pole noise coefficients re-fit for 48 kHz (same cutoff in Hz).
//   105_timp_wedge:  exc .14 knock .45 dscale 1  bloom 4ms  floor 0    noise 0
//   110_taiko_wedge: exc .11 knock .30 dscale 10 bloom 16ms floor .12  noise .18/2.8, cutoff .5->.008 sweep 2 Hz
struct ModalDrumRecipe {
    const ModalDrumMode* modes; int num_modes;
    const float* transient; int transient_len;
    float exc_gain;        // strike energy into the modes
    float knock_gain;      // broadband residual "knock" mix
    float decay_scale;     // >1 shortens all mode tails
    float bloom_ms;        // raised-cosine membrane swell to peak
    float bloom_floor;     // swell start level (0 = from silence)
    float noise_level;     // noise-wedge mix (0 = off)
    float noise_decay;     // noise-wedge env decay (1/s)
    float noise_coef_hi;   // wedge start cutoff (1-pole coeff @48k, bright)
    float noise_coef_lo;   // wedge end cutoff (dark)
    float noise_sweep_hz;  // cutoff sweep-down rate
    float out_gain;        // absolute output level (raw vel=1.0 peak -> 0.95)
    float root_note;       // MIDI note of the drum's dominant sustained partial (= shipped preset Note; Timpani 165.5 Hz -> E3/52)
};

static const ModalDrumRecipe kTimpaniRecipe = { kTimpaniModes, 280, kTimpaniTransient48, 3360, 0.14f, 0.45f, 1.0f, 4.0f, 0.00f, 0.00f, 3.0f, 0.471033f, 0.007352f, 6.0f, 0.961f, 52.0f };

